# ---------- 落盘 ----------
EXPECTED = {"B13": BATCHES["B13"], "B14": BATCHES["B14"], "B15": BATCHES["B15"]}
ALL_IDS = EXPECTED["B13"] + EXPECTED["B14"] + EXPECTED["B15"]
assert len(ALL_IDS) == 60, len(ALL_IDS)
assert set(DATA.keys()) == set(ALL_IDS), (set(ALL_IDS) - set(DATA.keys()), set(DATA.keys()) - set(ALL_IDS))

counts = {"changed_main": 0, "reserve_used": 0, "disputed": 0}
written = 0
for batch in ("B13", "B14", "B15"):
    ids = EXPECTED[batch]
    assert len(ids) == 20
    for cid in ids:
        pred, basis_body, conf, (cm, ru, di, reason) = DATA[cid]
        basis = "tradition：liuyao（卡面 tradition 字段逐字照录）\n" + basis_body
        obj = {
            "case_id": cid,
            "prediction_text": pred,
            "basis": basis,
            "confidence": conf,
            "trigger": {"changed_main": cm, "reserve_used": ru, "disputed": di, "reason": reason},
        }
        with open(f"{OUTDIR}/{cid}.json", "w", encoding="utf-8") as f:
            json.dump(obj, f, ensure_ascii=False, indent=1)
        written += 1
        counts["changed_main"] += int(cm)
        counts["reserve_used"] += int(ru)
        counts["disputed"] += int(di)
    print(f"{batch}: wrote {len(ids)}")

# 自验：逐件按本席 id 清单精确打开
ok = 0
for cid in ALL_IDS:
    d = json.load(open(f"{OUTDIR}/{cid}.json", encoding="utf-8"))
    assert d["case_id"] == cid and d["prediction_text"] and d["basis"].startswith("tradition：liuyao")
    assert set(d["trigger"].keys()) == {"changed_main", "reserve_used", "disputed", "reason"}
    ok += 1
print("written:", written, "verified:", ok)
print("trigger counts:", json.dumps(counts))
print("script bytes:", os.path.getsize(__file__))
